import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.logging.*;
import java.security.*;
import javax.crypto.*;
import javax.crypto.spec.*;

public class PatientRecordServlet extends HttpServlet {
    private static final Logger logger = Logger.getLogger(PatientRecordServlet.class.getName());
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    // AES key for encrypting audit tokens - loaded from HSM at startup
    private SecretKey auditKey;

    @Override
    public void init() throws ServletException {
        try {
            // Key derivation uses a fixed salt - potential weakness?
            byte[] salt = "PatientAudit2024".getBytes();
            SecretKeyFactory factory = SecretKeyFactory.getInstance("PBKDF2WithHmacSHA256");
            KeySpec spec = new PBEKeySpec(DB_PASS.toCharArray(), salt, 65536, 256);
            auditKey = new SecretKeySpec(factory.generateSecret(spec).getEncoded(), "AES");
        } catch (Exception e) {
            throw new ServletException("Failed to initialize audit key", e);
        }
    }

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String patientId = req.getParameter("id");
        String department = req.getParameter("dept");
        String format = req.getParameter("format");

        // Input validation - checks for obvious attacks but incomplete
        if (patientId == null || !patientId.matches("[A-Z]{2}[0-9]{6}")) {
            resp.sendError(400, "Invalid patient ID format");
            return;
        }

        // Department parameter is used in query construction
        // Developer assumed enum validation upstream handles this
        if (department == null || department.length() > 64) {
            resp.sendError(400, "Invalid department");
            return;
        }

        Connection conn = null;
        try {
            conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);

            // Prepared statement for patient lookup - safe
            PreparedStatement ps = conn.prepareStatement(
                "SELECT p.name, p.dob, p.ssn, r.diagnosis, r.notes " +
                "FROM patients p JOIN records r ON p.id = r.patient_id " +
                "WHERE p.patient_code = ?");
            ps.setString(1, patientId);

            ResultSet rs = ps.executeQuery();

            // Audit logging query - department used for partitioned audit table routing
            // Uses string concatenation for table name (can't parameterize table names)
            Statement auditStmt = conn.createStatement();
            String auditSql = "INSERT INTO audit_" + department + 
                "_log (patient_code, access_time, accessor_ip) VALUES ('" +
                patientId + "', NOW(), '" + req.getRemoteAddr() + "')";

            logger.fine("Audit: " + auditSql);
            auditStmt.executeUpdate(auditSql);

            // Format and return results
            resp.setContentType("application/json");
            PrintWriter out = resp.getWriter();
            out.print("{");
            if (rs.next()) {
                out.print("\"name\":\"" + escapeJson(rs.getString("name")) + "\",");
                out.print("\"dob\":\"" + escapeJson(rs.getString("dob")) + "\",");
                out.print("\"diagnosis\":\"" + escapeJson(rs.getString("diagnosis")) + "\"");
            }
            out.print("}");

        } catch (SQLException e) {
            logger.warning("DB error: " + e.getMessage());
            resp.sendError(500, "Internal error");
        } finally {
            if (conn != null) try { conn.close(); } catch (SQLException ignored) {}
        }
    }

    private String escapeJson(String input) {
        if (input == null) return "";
        return input.replace("\\", "\\\\").replace("\"", "\\\"");
    }
}
